def shuffleDeck(rightSide, leftSide):
    out = []
    idx = 0
    jdx = 0
    while idx < len(rightSide) and jdx < len(leftSide):
        if rightSide[idx] <= leftSide[jdx]:
            out.append(rightSide[idx])
            idx = idx + 1
        else:
            out.append(leftSide[jdx])
            jdx = jdx + 1
    return out + rightSide[idx:] + leftSide[jdx:]

